import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.BXzK3EA4.js";const h=JSON.parse('{"title":"Billing – Coupons","description":"","frontmatter":{"title":"Billing – Coupons"},"headers":[],"relativePath":"operations-knowledge-base/presales-support/billing-coupons.md","filePath":"operations-knowledge-base/presales-support/billing-coupons.md","lastUpdated":1794292919000}'),i={name:"operations-knowledge-base/presales-support/billing-coupons.md"};function n(r,e,l,u,p,d){return a(),o("div",null,[...e[0]||(e[0]=[s('<h2 id="_1-feature-overview" tabindex="-1">1. Feature Overview <a class="header-anchor" href="#_1-feature-overview" aria-label="Permalink to &quot;1. Feature Overview&quot;">​</a></h2><p>Coupons are discount tools provided by the platform that can be used to reduce the payable amount of eligible product orders, helping users enjoy promotional savings.</p><p>The “Coupons” page under the billing module supports coupon status statistics, filtering, and usage management.</p><h2 id="_2-access-path" tabindex="-1">2. Access Path <a class="header-anchor" href="#_2-access-path" aria-label="Permalink to &quot;2. Access Path&quot;">​</a></h2><p>Navigate to Customer Center → Billing → My Wallet, then click the “Coupons” tab in the top menu to enter the coupon management page.</p><h2 id="_3-feature-description" tabindex="-1">3. Feature Description <a class="header-anchor" href="#_3-feature-description" aria-label="Permalink to &quot;3. Feature Description&quot;">​</a></h2><h3 id="_1-status-statistics" tabindex="-1">(1) Status Statistics <a class="header-anchor" href="#_1-status-statistics" aria-label="Permalink to &quot;(1) Status Statistics&quot;">​</a></h3><p>At the top of the page, coupons are categorized and displayed by status:</p><ul><li>Expiring Soon - Number of coupons approaching their expiration date</li><li>Unused - Number of coupons currently available for use</li><li>Used - Number of coupons that have already been applied</li><li>Expired - Number of coupons that are no longer valid</li></ul><h3 id="_2-filters-and-list-information" tabindex="-1">(2) Filters and List Information <a class="header-anchor" href="#_2-filters-and-list-information" aria-label="Permalink to &quot;(2) Filters and List Information&quot;">​</a></h3><h4 id="status-filter" tabindex="-1">Status Filter <a class="header-anchor" href="#status-filter" aria-label="Permalink to &quot;Status Filter&quot;">​</a></h4><p>Use the “Status” dropdown menu to quickly filter coupons by category, such as:</p><ul><li>All Status</li><li>Unused</li><li>Used</li></ul><h4 id="coupon-list-information" tabindex="-1">Coupon List Information <a class="header-anchor" href="#coupon-list-information" aria-label="Permalink to &quot;Coupon List Information&quot;">​</a></h4><p>The coupon list displays the following key details:</p><p><strong>Name / Usage Details</strong> Shows the promotion name and specific usage rules (e.g., “December New User Promotion - $25 off orders over $100”).</p><p><strong>Amount / Discount</strong> Shows the discount amount or percentage provided by the coupon (e.g., $25 or 35%).</p><p><strong>Status / Renewal</strong> Shows the coupon’s current status (e.g., Unused) and whether it can be applied to renewal orders (e.g., Not Available).</p><p><strong>Time Information</strong> Includes the date received, expiration date, and usage date. If the coupon has not been used, the usage date will display “-”.</p><p><strong>Operation</strong> Click “Use Now” to go to the corresponding product order page, where the coupon can be applied according to its usage rules.</p><h3 id="_3-usage-rules" tabindex="-1">(3) Usage Rules <a class="header-anchor" href="#_3-usage-rules" aria-label="Permalink to &quot;(3) Usage Rules&quot;">​</a></h3><p>Coupons must meet the applicable usage conditions (e.g., “New user orders over $100”) and must be used within their validity period.</p><p>Coupons that have already been used or have expired cannot be used again. Users can check the coupon status in the list to confirm whether a coupon is still valid and available.</p>',23)])])}const g=t(i,[["render",n]]);export{h as __pageData,g as default};
